//! Port of `ExtLibs/Utilities/MissionFile.cs`
//!
//! `WaypointFile` reads the "QGC WPL" text format; `MissionFile` reads and writes QGroundControl
//! `.plan` JSON through Newtonsoft (classes generated by json2csharp), and converts between
//! its items and `Locationwp`.

#![allow(non_snake_case)]

use serde_json::Value;

use super::custommessagebox::CustomMessageBox;
use super::locationwp::Locationwp;
use crate::dotnet::io::{decode_detect, file_error, read_all_text, split_lines};
use crate::dotnet::json::{self, read_double, JsonObj, J};
use crate::dotnet::{double_parse_culture, float_parse_culture, int_parse, Exception, INVARIANT_CULTURE};
use crate::extlibs::mavlink::{CsEnum, MAV_CMD, MAV_FRAME};

fn null_reference() -> Exception {
    Exception::NullReference("Object reference not set to an instance of an object.".into())
}

fn list_index() -> Exception {
    Exception::ArgumentOutOfRange(
        "Index was out of range. Must be non-negative and less than the size of the collection.\r\nParameter name: index".into(),
    )
}

/// `Enum.Parse(typeof(MAVLink.MAV_CMD), s, false)` with the `(ushort)` cast: a member name
/// (case sensitive, comma lists OR-ed) or a number in range of the underlying ushort.
fn parse_mav_cmd(s: &str) -> Result<u16, Exception> {
    let t = s.trim();
    if t.is_empty() {
        return Err(Exception::Argument(
            "Must specify valid information for parsing in the string.".into(),
        ));
    }
    let first = t.chars().next().unwrap_or(' ');
    if first.is_ascii_digit() || first == '-' || first == '+' {
        // Convert.ChangeType(value, UInt16): UInt16.Parse. A FormatException falls through to
        // the name lookup; an out-of-range integer is an OverflowException.
        let (neg, digits) = match t.strip_prefix('-') {
            Some(d) => (true, d),
            None => (false, t.strip_prefix('+').unwrap_or(t)),
        };
        if !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()) {
            let zero = digits.bytes().all(|b| b == b'0');
            return match digits.parse::<u32>() {
                Ok(v) if (neg && zero) || (!neg && v <= u16::MAX as u32) => Ok(if neg { 0 } else { v as u16 }),
                _ => Err(Exception::Overflow("Value was either too large or too small for a UInt16.".into())),
            };
        }
    }
    match MAV_CMD::parse(t) {
        Some(c) => Ok(c.0 as u16),
        None => Err(Exception::Argument(format!("Requested value '{t}' was not found."))),
    }
}

/// `public class WaypointFile`
pub struct WaypointFile;

impl WaypointFile {
    /// `ReadWaypointFile(string file)`: a "QGC WPL" file to mission items. A first item whose
    /// index is not 0 gets a blank home inserted before it. Bad lines show "Line invalid" and
    /// are skipped; a missing header shows "Invalid Waypoint file". The message box throws when
    /// no UI has subscribed to it.
    pub fn ReadWaypointFile(file: &str) -> Result<Vec<Locationwp>, Exception> {
        let bytes = std::fs::read(file).map_err(|e| file_error(file, &e))?;
        let lines = split_lines(&decode_detect(&bytes));
        Self::read_waypoint_lines(lines, &mut |text| CustomMessageBox::show(text).map(|_| ()))
    }

    /// The body of `ReadWaypointFile` after the `StreamReader` has decoded the file, for
    /// callers that hold the text. `show` stands in for `CustomMessageBox.Show`: the app
    /// passes its own message display instead of subscribing to `ShowEvent`.
    pub fn read_waypoint_lines(
        lines: Vec<String>,
        show: &mut dyn FnMut(&str) -> Result<(), Exception>,
    ) -> Result<Vec<Locationwp>, Exception> {
        let mut wp_count = 0;
        let error = false;
        let mut cmds: Vec<Locationwp> = vec![];
        let mut it = lines.into_iter();
        let header = it.next();
        match &header {
            Some(h) if h.contains("QGC WPL") => {}
            _ => {
                show("Invalid Waypoint file")?;
                return Ok(cmds);
            }
        }

        // MissionFile.cs: `bool error = false; while (!error)`, never set inside the loop
        #[allow(clippy::while_immutable_condition)]
        while !error {
            let Some(line) = it.next() else { break };
            // waypoints

            if line.starts_with('#') {
                continue;
            }

            //seq/cur/frame/mode
            let items: Vec<&str> = line.split(['\t', ' ', ',']).filter(|s| !s.is_empty()).collect();

            if items.len() <= 9 {
                continue;
            }

            let r = (|| -> Result<(), Exception> {
                // check to see if the first wp is index 0/home.
                // if it is not index 0, add a blank home point
                if wp_count == 0 && items[0] != "0" {
                    cmds.push(Locationwp::default());
                }

                let mut temp = Locationwp::default();
                temp.frame = int_parse_invariant(items[2])? as u8;

                temp.id = parse_mav_cmd(items[3])?;
                temp.p1 = float_parse_culture(items[4], &INVARIANT_CULTURE)?;

                if temp.id == 99 {
                    temp.id = 0;
                }

                temp.alt = double_parse_culture(items.get(10).ok_or_else(crate::dotnet::index_out_of_range)?, &INVARIANT_CULTURE)? as f32;
                temp.lat = double_parse_culture(items[8], &INVARIANT_CULTURE)?;
                temp.lng = double_parse_culture(items[9], &INVARIANT_CULTURE)?;

                temp.p2 = double_parse_culture(items[5], &INVARIANT_CULTURE)? as f32;
                temp.p3 = double_parse_culture(items[6], &INVARIANT_CULTURE)? as f32;
                temp.p4 = double_parse_culture(items[7], &INVARIANT_CULTURE)? as f32;

                cmds.push(temp);

                wp_count += 1;
                Ok(())
            })();
            if let Err(ex) = r {
                log::error!("{ex}");
                show(&format!("Line invalid\n{line}"))?;
            }
        }

        Ok(cmds)
    }
}

/// `int.Parse(s, CultureInfo.InvariantCulture)`
fn int_parse_invariant(s: &str) -> Result<i32, Exception> {
    int_parse(s)
}

fn list_f64(v: &Value, path: &str) -> Result<Option<Vec<f64>>, Exception> {
    match v {
        Value::Null => Ok(None),
        Value::Array(a) => {
            let mut out = vec![];
            for (i, x) in a.iter().enumerate() {
                let p = format!("{path}[{i}]");
                out.push(read_double(x, &p)?.ok_or_else(|| {
                    Exception::JsonSerialization(format!("Error converting value {{null}} to type 'System.Double'. Path '{p}'."))
                })?);
            }
            Ok(Some(out))
        }
        _ => Err(Exception::JsonSerialization(format!("Error converting value to type 'System.Collections.Generic.List`1[System.Double]'. Path '{path}'."))),
    }
}

fn list_opt_f64(v: &Value, path: &str) -> Result<Option<Vec<Option<f64>>>, Exception> {
    match v {
        Value::Null => Ok(None),
        Value::Array(a) => {
            let mut out = vec![];
            for (i, x) in a.iter().enumerate() {
                out.push(read_double(x, &format!("{path}[{i}]"))?);
            }
            Ok(Some(out))
        }
        _ => Err(Exception::JsonSerialization(format!("Error converting value to type 'System.Collections.Generic.List`1[System.Nullable`1[System.Double]]'. Path '{path}'."))),
    }
}

fn list_of<T>(v: &Value, path: &str, f: impl Fn(&Value, &str) -> Result<Option<T>, Exception>) -> Result<Option<Vec<T>>, Exception> {
    match v {
        Value::Null => Ok(None),
        Value::Array(a) => {
            let mut out = vec![];
            for (i, x) in a.iter().enumerate() {
                let p = format!("{path}[{i}]");
                match f(x, &p)? {
                    Some(t) => out.push(t),
                    None => return Err(Exception::JsonSerialization(format!("Error converting value {{null}}. Path '{p}'."))),
                }
            }
            Ok(Some(out))
        }
        _ => Err(Exception::JsonSerialization(format!("Error converting value to a list. Path '{path}'."))),
    }
}

/// Wraps an object-typed property reader: absent or null is null.
fn prop<'a, T>(o: &JsonObj<'a>, name: &str, f: impl Fn(&'a Value, &str) -> Result<Option<T>, Exception>) -> Result<Option<T>, Exception> {
    match o.get(name) {
        None => Ok(None),
        Some((v, path)) => f(v, &path),
    }
}

fn j_opt<T>(v: &Option<T>, f: impl Fn(&T) -> J) -> J {
    match v {
        Some(x) => f(x),
        None => J::Null,
    }
}

fn j_list_f64(v: &[f64]) -> J {
    J::Arr(v.iter().map(|x| J::Double(*x)).collect())
}

fn j_str(v: &Option<String>) -> J {
    j_opt(v, |s| J::Str(s.clone()))
}

